              "content": "米30年国債利回りが一時5.5%を突破しました。急速な金利上昇に対し、市場では「何かが壊れる（金融事故が起きる）」という歴史的な警戒感が高まっています。これに連動して住宅ローン金利も7%を超え、住宅市場の凍結が鮮明になっています。",
