  "glossary": {
    "AIエージェント": "自律的に目標を設定し、外部ツールやウェブサイトを操作してタスクを実行するAIシステム。高度な利便性の一方で、意図しない動作（暴走）のリスクが指摘されています。",
    "リフレ政策": "デフレ脱却を目指し、通貨供給量を増やして緩やかなインフレ（物価上昇）を誘致する経済政策。日本の経財相がその終焉を示唆したことは、長年の金融緩和策の転換を意味します。",
    "10年債利回り": "償還期間が10年の国債の利回り。長期金利の代表的な指標であり、住宅ローン金利や企業の借入金利、さらには為替相場に多大な影響を与えます。",
    "ハイブリッド戦争": "正規軍による武力攻撃だけでなく、サイバー攻撃、情報操作、経済的圧力などを組み合わせ、相手国の社会を混乱させる非対称的な紛争形態。",
    "エルニーニョ現象": "太平洋赤道域の海水温が平年より高くなる現象。世界的な異常気象を引き起こし、農業生産やインフラ、経済活動に数兆ドル規模の損失をもたらすと予測されています。",
    "ホルムズ海峡": "ペルシャ湾とオマーン湾を繋ぐ海上輸送の要衝。世界の原油輸送の約2割が通過するため、この海域の緊張は即座にエネルギー価格の高騰を招きます。",
    "サプライチェーン": "製品の原材料調達から製造、在庫管理、配送、販売までの一連の供給網。紛争や災害による「断絶」が世界経済の大きなリスク要因となっています。",
    "ランサムウェア": "データを暗号化して使用不能にし、復旧と引き換えに身代金（ランサム）を要求する不正プログラム。インフラ企業への攻撃が社会問題化しています。"
  },
